import pandas as pd
import seaborn as sns
import numpy as np
import ast

def task_func(csv_file):
    df = pd.read_csv(csv_file)

    if "email" not in df.columns:
        raise KeyError("CSV must contain an 'email' column.")
    if "list" not in df.columns:
        raise KeyError("CSV must contain a 'list' column.")

    def _parse_list(value):
        if isinstance(value, (list, tuple, np.ndarray, pd.Series)):
            return list(value)
        if pd.isna(value):
            return []
        if isinstance(value, str):
            text = value.strip()
            if not text:
                return []
            try:
                parsed = ast.literal_eval(text)
            except (ValueError, SyntaxError):
                parsed = [item.strip() for item in text.strip("[]()").split(",") if item.strip()]
            if isinstance(parsed, (list, tuple, np.ndarray, pd.Series)):
                return list(parsed)
            return [parsed]
        return [value]

    def _calculate_stats(values):
        series = pd.to_numeric(pd.Series(values), errors="coerce").dropna()
        if series.empty:
            return 0.0, np.nan, np.nan
        total = float(series.sum())
        mean = float(series.mean())
        std = float(series.std(ddof=1)) if len(series) > 1 else np.nan
        return total, mean, std

    parsed_lists = df["list"].apply(_parse_list)

    records = []
    for email, values in zip(df["email"], parsed_lists):
        total, mean, std = _calculate_stats(values)
        records.append(
            {
                "email": email,
                "list": values,
                "sum": total,
                "mean": mean,
                "std": std,
            }
        )

    result_df = pd.DataFrame(records, columns=["email", "list", "sum", "mean", "std"])

    mean_values = result_df["mean"].dropna()
    ax = sns.histplot(data=mean_values if not mean_values.empty else pd.Series(dtype=float))
    ax.set_xlabel("Mean")
    ax.set_ylabel("Count")
    ax.set_title("Histogram of Mean Values")

    return result_df, ax

