import pandas as pd
import numpy as np
import itertools
from datetime import datetime, timedelta
import seaborn as sns

def task_func(df, fruits=None, days=None, seed=None, sales_lower_bound=1, sales_upper_bound=50):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("'df' must be a pandas DataFrame")

    if not df.empty:
        raise ValueError("'df' must be empty")

    if sales_lower_bound >= sales_upper_bound:
        raise ValueError("'sales_lower_bound' must be less than 'sales_upper_bound'")

    if fruits is None:
        fruits = ["Apple", "Banana", "Orange"]
    elif isinstance(fruits, str):
        fruits = [fruits]
    else:
        fruits = list(fruits)

    if days is None:
        days = range(7)
    elif isinstance(days, int):
        days = range(days)
    elif isinstance(days, str):
        days = [days]
    else:
        days = list(days)

    if len(fruits) == 0:
        raise ValueError("'fruits' must not be empty")
    if len(days) == 0:
        raise ValueError("'days' must not be empty")

    rng = np.random.default_rng(seed)
    base_date = datetime(2000, 1, 1)

    records = []
    for fruit, day in itertools.product(fruits, days):
        if isinstance(day, (int, np.integer)):
            date_value = base_date + timedelta(days=int(day))
        elif isinstance(day, datetime):
            date_value = day
        else:
            try:
                date_value = pd.to_datetime(day).to_pydatetime()
            except Exception:
                date_value = base_date + timedelta(days=int(day))

        sales_value = int(rng.integers(sales_lower_bound, sales_upper_bound))
        records.append({"fruit": fruit, "date": date_value, "sales": sales_value})

    generated_df = pd.DataFrame.from_records(records)
    updated_df = pd.concat([df.copy(), generated_df], ignore_index=True)

    plot = sns.catplot(data=updated_df, x="fruit", y="sales", kind="box")

    return updated_df, plot

