from collections import Counter

def task_func(json_str, top_n=10):
    """
    Extract URLs from a JSON-serialized dictionary-like string and count occurrences.

    Args:
        json_str: A string containing JSON data.
        top_n: Kept for compatibility with the required signature; all URLs are returned.

    Returns:
