    """
    url_pattern = re.compile(r'(?i)\b(?:https?://|www\.)[^\s<>"\'`]+')
    trailing_punct = '.,;:!?)\]}>\'"'

    def clean_url(url: str) -> str:
        return url.rstrip(trailing_punct)

    def extract_from_text(text: str):
        urls = []
        for match in url_pattern.finditer(text):
            url = clean_url(match.group(0))
            if url:
                urls.append(url)
        return urls

    def walk(obj):
        urls = []
        if isinstance(obj, str):
            urls.extend(extract_from_text(obj))
        elif isinstance(obj, dict):
            for key, value in obj.items():
                if isinstance(key, str):
                    urls.extend(extract_from_text(key))
                urls.extend(walk(value))
        elif isinstance(obj, (list, tuple, set)):
            for item in obj:
                urls.extend(walk(item))
        return urls

    try:
        data = json.loads(json_str)
    except (TypeError, json.JSONDecodeError):
        data = json_str if isinstance(json_str, str) else ""

    counts = Counter(walk(data))
    return dict(counts)

