    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    normalized = {}
    for key, value in data.items():
        if isinstance(value, dict):
            return pd.DataFrame()
        normalized[key] = _double_value(value)

    list_lengths = []
    for value in normalized.values():
        if isinstance(value, (list, tuple)):
            list_lengths.append(len(value))

    if not list_lengths:
        return pd.DataFrame([normalized])

    if any(length == 0 for length in list_lengths):
        return pd.DataFrame()

    target_len = max(list_lengths)
    valid_lengths = {1, target_len}
    if any(length not in valid_lengths for length in list_lengths):
        return pd.DataFrame()

    frame_data = {}
