def _parse_timezone(timezone_name):
    """
    Return a tuple of (timezone_label, tzinfo) for valid timezones.
    Supports pytz timezones and UTC±HH:MM fixed offsets.
    """
    if timezone_name in pytz.all_timezones:
        return timezone_name, pytz.timezone(timezone_name)

    match = _UTC_OFFSET_PATTERN.fullmatch(timezone_name)
    if match:
