    archive_path = os.path.join(target_dir, os.path.basename(archive_name))
    processed_pattern = re.compile(r"_processed(?:\.[^.\\/]+)*$")

    def _is_within(child_path: str, parent_path: str) -> bool:
        try:
            return os.path.commonpath([os.path.abspath(child_path), os.path.abspath(parent_path)]) == os.path.abspath(parent_path)
